# POST /api/sheets/{sheetId}/claims/paste — add a DRAFT claim per pasted line. Body {"text":"..."}, lines of
# name,amount,date,note (a blank date is the entry date, else the sheet's today; the note may hold commas or be absent, and may end in " #<reference>": that part is the claim's reference, not its note). Every line is
# checked first, by the claim form's rules and against a person of that name (ignoring case) on the sheet: 400 for a
# bad line, a name not on the sheet, a reference already used on the sheet or repeated in the paste (ignoring case), 422 for a date inside a closed period or after the person's retirement —
# and then nothing is stored. Responds {"added":n}.
viewer:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: archived
  govern: [ transaction ]
archived:
  class: net.officefloor.hq.app.sheet.RefuseArchived
  next: snapshot
  govern: [ transaction ]
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  next: validate
  govern: [ transaction ]
validate:
  class: net.officefloor.hq.app.claim.ValidatePaste
  next: add
  govern: [ transaction ]
add:
  class: net.officefloor.hq.app.claim.AddPastedClaims
  next: rollup
  govern: [ transaction ]
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  next: respond
  govern: [ transaction ]
respond:
  class: net.officefloor.hq.app.claim.RespondWithPasted
  govern: [ transaction ]
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.holiday.Holidays;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;

public class AddPastedClaims {
    // Each checked line becomes a DRAFT claim, in order, added as the claim form adds one and recorded as CLAIM_ADDED.
    public void add(@Val PastedLines pasted, Claims claims, Sheets sheets, Settings settings, Holidays holidays, Rollup rollup,
            ServerHttpConnection connection, Audit audit, Out<PasteResponse> result) {
        String user = Audit.user(connection);
        for (PastedLine line : pasted.lines()) {
            Person person = line.person();
            ClaimInput input = line.input();
            LocalDate today = sheets.today(person.sheetId());
            LocalDate date = input.date() != null ? input.date() : settings.entryDate(person.sheetId());
            int terms = person.termsOn(date, settings);
            LocalDate dueBy = holidays.dueBy(person.sheetId(), date, terms);
            Claim claim = claims.add(person.sheetId(), person.id(), input.amount(), date, input.note(), null, dueBy, terms, input.ref(),
                    input.tags());
            claims.log(claim, user.trim(), today, rollup.figure(claim));
            ClaimResponse shown = ClaimResponse.from(claim);
            audit.record(claim.ref() == null
                    ? Audit.line("CLAIM_ADDED", claim.sheetId(), user, "person=" + person.name(),
                            "amount=" + shown.amount(), "date=" + shown.date())
                    : Audit.line("CLAIM_ADDED", claim.sheetId(), user, "person=" + person.name(),
                            "amount=" + shown.amount(), "date=" + shown.date(), "ref=" + claim.ref()));
            if (claim.lateEntry()) {
                audit.record(Audit.line("LATE_ENTRY", claim.sheetId(), user, "person=" + person.name(),
                        "amount=" + shown.amount(), "date=" + shown.date()));
            }
        }
        result.set(new PasteResponse(pasted.lines().size()));
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.holiday.Holidays;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;
import java.util.List;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidatePaste {
    // Every line is checked before any is added: name,amount,date,note — the name a person's name or alias on the sheet (ignoring
    // case and surrounding spaces), the rest by the claim form's rules (a blank date is the entry date, else the sheet's today, the note
    // may hold commas or be absent). A note ending in " #<reference>" gives the claim that reference (that part is not
    // the note), refused when the sheet or an earlier line already uses it (ignoring case). Blank lines are skipped; a
    // paste with no line is refused.
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody PasteRequest body, People people,
            Claims claims, Settings settings, Holidays holidays, Periods periods, Out<PastedLines> out)
            throws InvalidClaimException, ClaimInClosedPeriodException, ClaimAfterRetirementException {
        String sheet = sheetId.trim();
        String text = body == null || body.text() == null ? "" : body.text();
        List<PastedLine> lines = new ArrayList<>();
        Set<String> refs = new HashSet<>();
        int n = 0;
        for (String line : text.split("\\r?\\n")) {
            n++;
            if (line.isBlank()) {
                continue;
            }
            String[] fields = line.split(",", 4);
            if (fields.length < 2) {
                throw new InvalidClaimException("Line " + n + ": type name,amount,date,note.");
            }
            String name = fields[0].trim();
            Person person = name.isEmpty() ? null : people.findByName(sheet, name);
            if (person == null) {
                throw new InvalidClaimException("Line " + n + ": no person " + name + " on this sheet.");
            }
            String note = fields.length > 3 ? fields[3].trim() : "";
            String ref = "";
            int hash = note.lastIndexOf(" #");
            if (hash >= 0) {
                ref = note.substring(hash + 2);
                note = note.substring(0, hash);
            }
            ClaimInput input;
            try {
                input = ValidateClaim.parse(new ClaimRequest(fields[1], fields.length > 2 ? fields[2] : "", note, "", ref, ""));
                if (input.ref() != null && !refs.add(input.ref().toLowerCase(Locale.ROOT))) {
                    throw new InvalidClaimException("The reference " + input.ref() + " is given twice in the paste.");
                }
                RefuseUsedRef.refuse(input.ref(), sheet, 0, claims);
            } catch (InvalidClaimException e) {
                throw new InvalidClaimException("Line " + n + ": " + e.getMessage());
            }
            LocalDate date = input.date() != null ? input.date() : settings.entryDate(sheet);
