package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.holiday.Holidays;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;

public class AddClaim {
    // The due-by is fixed now: the claim's date plus the person's own terms, else the terms of
    // their grade in force on that date (the sheet's when the grade has none), moved past the sheet's holidays as they
    // are now: on a holiday it is the next day that is not one.
    // Its status log starts with its DRAFT line, at its due as shown now.
    public void add(@Val ClaimInput input, @Val Person person, Claims claims, Sheets sheets, Settings settings,
            Holidays holidays, Rollup rollup, ServerHttpConnection connection, Out<Claim> claimOut) {
        LocalDate date = input.date() != null ? input.date() : settings.entryDate(person.sheetId());
        int terms = person.termsOn(date, settings);
        LocalDate dueBy = holidays.dueBy(person.sheetId(), date, terms);
        Claim claim = claims.add(person.sheetId(), person.id(), input.amount(), date, input.note(), input.corrects(),
                dueBy, terms, input.ref(), input.tags());
        claims.log(claim, Audit.user(connection).trim(), sheets.today(person.sheetId()), rollup.figure(claim));
        claimOut.set(claim);
    }
}
-- A transfer merged into a person on the other sheet joins their aliases (as a merge does), so an alias may come twice
-- on a sheet in differing case (Addie and addie): alias_key is no longer unique, only indexed. The app still refuses
-- an alias that is taken when one is added.
ALTER TABLE person_alias DROP CONSTRAINT person_alias_sheet_key;
CREATE INDEX person_alias_sheet_key ON person_alias (sheet_id, alias_key);
-- A person's aliases, kept without surrounding spaces. They share the names' uniqueness on the sheet, compared
-- without regard to case: alias_key is the lower-cased alias, unique on the sheet (an alias equal to a name is
-- refused by the app). The quick-add bar and the paste box find a person by an alias as well as by the name.
CREATE TABLE person_alias (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    person_id BIGINT       NOT NULL REFERENCES person (id),
    sheet_id  VARCHAR(255) NOT NULL,
    alias     VARCHAR(255) NOT NULL,
    alias_key VARCHAR(255) GENERATED ALWAYS AS (LOWER(alias))
);
ALTER TABLE person_alias ADD CONSTRAINT person_alias_sheet_key UNIQUE (sheet_id, alias_key);
CREATE INDEX person_alias_person ON person_alias (person_id);
-- The sheet's claim templates: a name (trimmed, at most once per sheet), an amount and a note. Saving a name again
-- replaces its amount and note. A claim made from a template copies them, so a later save does not alter it.
CREATE TABLE claim_template (
    sheet_id VARCHAR(255) NOT NULL,
    name VARCHAR(255) NOT NULL,
    amount DECIMAL(19, 2) NOT NULL,
    note VARCHAR(1000) NOT NULL,
    listed BIGINT NOT NULL,
    PRIMARY KEY (sheet_id, name)
);
# GET /api/sheets/{sheetId}/templates — the sheet's claim templates, in the order first saved ({name, amount, note}).
respond:
  class: net.officefloor.hq.app.template.RespondWithTemplates
  govern: [ readonly-transaction ]
package net.officefloor.hq.app.template;

import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The store of the sheet's claim templates, each name at most once per sheet. */
@Repository
public class ClaimTemplates {

    private final JdbcTemplate jdbc;

    public ClaimTemplates(JdbcTemplate jdbc) {
