import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { usePersonError } from './usePersonError';
import { useUser } from '../session/useUser';
import { peopleKey, peopleQuery } from './peopleQuery';
import type { Person } from './peopleQuery';

/**
 * The person's aliases, sorted as names are compared, and the control that adds one. An alias shares the names'
 * uniqueness across the sheet's tree: one equal (ignoring case) to any name or alias there is refused, as is a blank one.
 */
function PersonAliases({ sheetId, personId }: { sheetId: string; personId: number }) {
  const queryClient = useQueryClient();
  const [user] = useUser();
  const [alias, setAlias] = useState('');
  const [, setError] = usePersonError(personId);
  const once = useSubmitOnce();
  const person = (useQuery(peopleQuery(sheetId)).data ?? []).find((p) => p.id === personId);
  const add = useMutation({
    mutationFn: (body: { alias: string }) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/aliases`, body, user),
    onSuccess: async () => {
      setAlias('');
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
    },
    onError: () => setError('The alias could not be added: it is blank or already in use.'),
  });

  return (
    <td>
      <span data-testid="person-aliases">{(person?.aliases ?? []).join(', ')}</span>{' '}
      <input
        data-testid="person-alias-input"
        placeholder="alias"
        value={alias}
        onChange={(e) => {
          setAlias(e.target.value);
          setError('');
        }}
      />{' '}
      <button
        type="button"
        data-testid="person-alias-add"
        disabled={add.isPending}
        onClick={() => {
          setError('');
          const a = alias.trim();
          if (a === '') {
            setError('Type an alias.');
            return;
          }
          once(() => add.mutateAsync({ alias: a }));
        }}
      >
        Add alias
      </button>
    </td>
  );
}

// The row's `person-error` is shown by the hold cell, shared by every cell acting on the person.
export const contributions = [
  PersonHeaders.fill({ order: 9, Component: () => <th>Aliases</th> }),
  PersonCells.fill({ order: 9, Component: PersonAliases }),
];
import { getJson } from '../../api/http';
import { heldOn, type Person } from '../people/peopleQuery';
import { sheetKey } from '../sheet/sheetQuery';

export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID' | 'DELETED';

/** An open claim: OPEN, or PENDING (settled by a clerk above the clerk limit, awaiting a steward), handled like OPEN in every total. */
export const isOpen = (c: Claim) => c.status === 'OPEN' || c.status === 'PENDING';

/**
 * `amount` has two decimals ("12.50"); `date` is yyyy-mm-dd; `number` is given on opening and kept when voided (null for a draft);
 * `settledDue` is the due fixed on settling (null when not settled, or settled while no rate applied on the claim's date);
 * `openedBy` is the user who opened it (null when never opened), who cannot settle it;
 * `stated` is whether its person's last statement bound it, at `statedDue` (null when it had no figure then) — a PENDING claim is not bound while PENDING;
 * a negative `amount` is a correction, and `corrects` is the number of the settled claim it corrects (null for any other claim);
 * `dueBy` (yyyy-mm-dd) is fixed when the claim is made, from its person's own terms, else the terms of their grade on its date, counted in business days after its date (skipping Saturdays, Sundays and the sheet's holidays as they then were), and kept when they or its date change;
 * `log` is its status log, oldest first, one line per status it has had: "<STATUS> by <user> on <date> due=<due>";
 * `deferredUntil` (yyyy-mm-dd) is the date an OPEN claim was deferred to (null when never deferred), see `isDeferred`;
 * `proofs` is how many proofs it has been given: one above the sheet's proof threshold is settled or approved only with one;
 * `splitFrom` is the number of the claim it was split off (null for any other claim);
 * `lockedBy` is the user whose open editor locks it for everyone else (null when not locked);
 * `lateEntry` is whether it was added while the period its due-by falls in was soft-closed;
 * `remindedOn` (yyyy-mm-dd) is the last sheet's today a reminder was written for it (null when never reminded);
 * `ref` is its external reference, unique on the sheet without regard to case (null when it has none);
 * `tags` are its tags, trimmed, lower-cased, without repeats and sorted (empty for none);
 * `comments` are its comments, oldest first, each "<user> on <date>: <text>" with the sheet's today when written;
 * `batch` is the number of the settle batch (a bulk settle) that settled it (null when none, or settled one at a time).
 */
export type Claim = {
  id: number;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string | null;
  settledDue: string | null;
  openedBy: string | null;
  stated: boolean;
  statedDue: string | null;
  corrects: string | null;
  dueBy: string;
  log: string[];
  deferredUntil: string | null;
  proofs: number;
  splitFrom: string | null;
  lockedBy: string | null;
  lateEntry: boolean;
  remindedOn: string | null;
  ref: string | null;
  tags: string[];
  comments: string[];
  batch: number | null;
};

/** A correction: its due is its amount times the rate, with no floor and no late charge. */
export const isCorrection = (c: Claim) => Number(c.amount) < 0;

/**
 * An OPEN claim deferred to a date the sheet's `today` has not reached: it counts in no total, is not overdue and
 * cannot be settled. From that day on it is an OPEN claim like any other.
 */
export const isDeferred = (c: Claim, today: string) =>
  c.status === 'OPEN' && c.deferredUntil !== null && (today === '' || today < c.deferredUntil);

/**
 * Only open (OPEN or PENDING) and SETTLED claims count toward claimed, due and every total; drafts, voided and
 * deleted ones do not, nor do a person's open claims dated within one of their holds, or once the sheet's `today` reaches
 * their retirement date, unless a statement bound them, nor an OPEN claim deferred on the sheet's `today`.
 */
export const counts = (c: Claim, people: Person[], today: string) =>
  !isDeferred(c, today) &&
  (c.status === 'SETTLED' ||
  (isOpen(c) &&
    ((c.stated && c.status !== 'PENDING') || !leftOut(people.find((p) => p.id === c.personId), c.date, today))));

/** Whether the person's unbound open claim dated `date` is left out: within a hold, or retired by `today`. */
const leftOut = (person: Person | undefined, date: string, today: string) =>
  heldOn(person, date) || (!!person?.retiredFrom && !!today && person.retiredFrom <= today);

/** The first day (yyyy-mm-dd) of the 30 days up to and including the sheet's `today`. */
const activeFrom = (today: string) => new Date(Date.parse(`${today}T00:00:00Z`) - 29 * 86_400_000).toISOString().slice(0, 10);

/**
 * Whether the person is active: they have an open (OPEN or PENDING) claim that counts, dated within the 30 days up to
 * and including the sheet's `today` (never while `today` is not loaded).
 */
export function isActive(personId: number, claims: Claim[], people: Person[], today: string): boolean {
  if (today === '') return false;
  const from = activeFrom(today);
  return claims.some(
    (c) => c.personId === personId && isOpen(c) && counts(c, people, today) && from <= c.date && c.date <= today,
  );
}

/** Under the sheet's key, so re-loading the sheet re-reads its claims. */
export const claimsKey = (sheetId: string) => [...sheetKey(sheetId), 'claims'] as const;

/** Under the claims' key, so whatever re-reads the claims re-reads the last settle batch too. */
export const settleBatchKey = (sheetId: string) => [...claimsKey(sheetId), 'settle-batch'] as const;

/** The number of the sheet's last settle batch (`last` null when it has had none). */
export const settleBatchQuery = (sheetId: string) => ({
  queryKey: settleBatchKey(sheetId),
  queryFn: () => getJson<{ last: number | null }>(`/api/sheets/${encodeURIComponent(sheetId)}/settle-batches`),
});

/** Every claim on the sheet, newest first. */
export const claimsQuery = (sheetId: string) => ({
  queryKey: claimsKey(sheetId),
  queryFn: () => getJson<Claim[]>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`),
});

/** Under the claims' key, so whatever re-reads the claims re-reads the tags too. */
export const tagsKey = (sheetId: string) => [...claimsKey(sheetId), 'tags'] as const;

/** Every tag ever carried by a claim of the sheet, sorted (kept once used, even when no claim carries it now). */
export const tagsQuery = (sheetId: string) => ({
  queryKey: tagsKey(sheetId),
  queryFn: () => getJson<string[]>(`/api/sheets/${encodeURIComponent(sheetId)}/tags`),
});

/** Amounts are added up in whole cents, so the sum shows exactly with two decimals. */
export function sumAmounts(claims: Claim[]): string {
  const cents = claims.reduce((total, c) => total + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}
import { getJson } from '../../api/http';

/** `today` is the sheet's own date (yyyy-mm-dd): use it, never the real clock, for anything dated.
 *  An `archived` sheet shows everything and refuses every change. */
export type Sheet = { id: string; today: string; archived: boolean };

/** Every query kept per sheet lives under this key, so re-loading a sheet re-reads all of it. */
export const sheetKey = (sheetId: string) => ['sheet', sheetId] as const;

export const sheetQuery = (sheetId: string) => ({
  queryKey: sheetKey(sheetId),
  queryFn: () => getJson<Sheet>(`/api/sheets/${encodeURIComponent(sheetId)}`),
});
import { currentAsOf } from './asOf';

// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A write refused because the record was saved by someone else since it was loaded (409). */
export class ConflictError extends Error {}

/** A write refused by a rule the screen cannot see in full (422), e.g. a claim dated in a closed period; the message is the server's. */
export class RefusedError extends Error {}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  // A screen shown as of a date names it on every request: reads come back as of it, changes are refused (422).
  const asOf = currentAsOf();
  const res = await fetch(path, asOf ? { ...init, headers: { ...init?.headers, 'X-As-Of': asOf } } : init);
  if (res.status === 409) {
    throw new ConflictError(`${init?.method ?? 'GET'} ${path} -> 409`);
  }
  if (res.status === 422) {
    throw new RefusedError(await res.text());
  }
  if (!res.ok) {
    throw new Error(`${init?.method ?? 'GET'} ${path} -> ${res.status}`);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

// A write names the signed-in user (X-User) so the server can record who made the change.
function jsonHeaders(user?: string): HeadersInit {
  return user ? { 'Content-Type': 'application/json', 'X-User': user } : { 'Content-Type': 'application/json' };
}

export function postJson<T>(path: string, body: unknown, user?: string): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: jsonHeaders(user),
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown, user?: string): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: jsonHeaders(user),
    body: JSON.stringify(body),
  });
}
import { useRef } from 'react';

/**
 * Guard a form's submit so a second submit while the first is still unanswered (a double click)
 * sends nothing. The guard is a ref, set synchronously, so it holds before React re-renders the
 * button as disabled.
 *
 *     const once = useSubmitOnce();
 *     once(() => save.mutateAsync(body));
 */
export function useSubmitOnce() {
  const busy = useRef(false);
  return (run: () => Promise<unknown>) => {
    if (busy.current) return;
    busy.current = true;
    run()
      .catch(() => undefined) // the mutation's onError shows the refusal
      .finally(() => {
        busy.current = false;
      });
  };
}

